var n=`0832-vindaloo`;var t=`world-0832`;var a=`IN`;var s=`south-asia`;var o=4;var r=201;var g={en:`Vindaloo`,ua:`Віндалу`};var d={en:`Vindaloo is a India dish made with pork shoulder, white vinegar, ginger-garlic paste, yellow onion. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Віндалу, страва кухні країни Індія. Основні складники: свиняча лопатка, білий оцет, імбирно-часникова паста, жовта цибуля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 120 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 120 хвилин.`,t:[`marinating`],m:120,i:[[`pork-shoulder`,780,`g`],[`white-vinegar`,70,`ml`],[`ginger-garlic-paste`,35,`g`],[`cayenne-pepper-powder`,8,`g`],[`ground-cumin`,6,`g`],[`ground-turmeric`,3,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 13 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 13 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:13,i:[[`yellow-onion`,200,`g`],[`canola-oil`,50,`ml`],[`tomato-paste`,45,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 65 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 65 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:65,i:[[`water`,480,`ml`],[`brown-sugar`,18,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`]]}];var u={slug:n,id:t,country:`IN`,region:s,servings:4,minutes:201,title:g,text:d,steps:l};export{a as country,u as default,t as id,r as minutes,s as region,o as servings,n as slug,l as steps,d as text,g as title};